<script setup lang="ts">
const {t}=useI18n(),route=useRoute(),{bizErrorMessage}=useBizError()
const data=ref<any>(null),key=ref<any>(null),error=ref(''),loading=ref(false),page=ref(1),status=ref(''),from=ref(''),before=ref('')
let generation=0
const columns=computed(()=>[{key:'called_at',label:t('api-calls.time')},{key:'method',label:t('api-calls.method')},{key:'route',label:t('api-calls.route')},{key:'status_code',label:t('api-calls.status')},{key:'duration_ms',label:t('api-calls.duration')}])
const load=async()=>{const seq=++generation;loading.value=true;error.value='';data.value=null;const result=await httpRequest<any>('/api/system/third-party/api-keys/'+route.params.id+'/calls',{params:{page:page.value,per_page:20,status:status.value||undefined,from:from.value?new Date(from.value+'T00:00:00').toISOString():undefined,before:before.value?new Date(before.value+'T00:00:00').toISOString():undefined},onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation){data.value=result;loading.value=false}}
const filter=()=>{page.value=1;load()}
onMounted(async()=>{key.value=await httpRequest<any>('/api/system/third-party/api-keys/'+route.params.id,{onError:e=>error.value=bizErrorMessage(e)});if(key.value)load()});onBeforeUnmount(()=>generation++)
useHead({title:()=>t('api-calls.title')})
</script>
<template><div class="api-calls w-scope"><header><div><NuxtLink to="/apikeys">{{t('nav.apikeys')}}</NuxtLink><h1>{{t('api-calls.title')}}<small>{{key?.system_name}}</small></h1></div><WButton :disabled="loading" @click="load">{{t('freight.reload')}}</WButton></header><p>{{t('api-calls.hint')}}</p><WCard flush><form @submit.prevent="filter"><WField :label="t('api-calls.from')"><WInput v-model="from" type="date"/></WField><WField :label="t('api-calls.before')"><WInput v-model="before" type="date"/></WField><WField :label="t('api-calls.status')"><select :aria-label="t('api-calls.status')" v-model="status" class="status-select"><option value="">{{t('common.status.all')}}</option><option v-for="value in ['2xx','3xx','4xx','5xx']" :key="value">{{value}}</option></select></WField><WButton type="submit" :disabled="loading">{{t('common.search')}}</WButton></form><WAlert v-if="error" tone="block" :title="error"/><WTable :rows="data?.items||[]" :columns="columns" :loading="loading" inset><template #cell-called_at="{row}">{{$dayjs(row.called_at,'YYYY-MM-DD HH:mm:ss')}}</template><template #cell-route="{row}"><code>{{row.route}}</code></template><template #cell-status_code="{row}"><WStatus :tone="row.status_code>=400?'bad':'ok'">{{row.status_code}}</WStatus></template><template #cell-duration_ms="{row}">{{row.duration_ms}} ms</template></WTable><footer><WPagination :page="page" :page-size="20" :total="data?.total||0" show-total @update:page="value=>{page=value;load()}"/></footer></WCard></div></template>
<style scoped>.api-calls{display:flex;flex-direction:column;gap:16px}header{display:flex;justify-content:space-between;align-items:center;gap:12px}header a,p{font-size:13px;color:var(--w-text-3)}h1{font-size:24px;margin:6px 0 0}h1 small{font-size:14px;margin-left:12px;font-weight:400}p{margin:0}form{display:flex;align-items:end;flex-wrap:wrap;gap:12px;padding:16px 20px}.status-select{height:36px;border:1px solid var(--w-border);border-radius:6px;padding:0 12px;background:white}footer{padding:12px 20px;border-top:1px solid var(--w-border)}code{overflow-wrap:anywhere}.api-calls :deep(table){min-width:680px}</style>
